const D = { density:.5, energy:.55, speed:1, scale:1, taper:.55, spread:.5, hue:45, x:.5, y:.55, style:'hyphae', act:'grow', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const W=width, Hh=height, u=Math.min(W,Hh);
const clp=(v,a,b)=>Math.max(a,Math.min(b,v));
const lrp=(a,b,t)=>a+(b-a)*t;
const md=(a,n)=>((a%n)+n)%n;
const st=P.style;
const intn=(K.intensity!=null?K.intensity:.6);
const en=clp(P.energy,0,1);
const dens=clp(P.density,0,1);
const aMul=clp(P.alpha,0,100)/100;

// tolerate t0 / clock resets (K.t can jump backwards)
if(S.buildT==null || K.t < S.buildT-0.5) S.buildT=K.t;
if(S.doneAt==null || K.t < S.doneAt-0.5) S.doneAt=K.t;

// ---------- static ground buffer (cached per size/style/seed) ----------
const gkey=W+'x'+Hh+'|'+st+'|'+(P.seed|0);
if(!S.ground || S.gkey!==gkey){
  S.gkey=gkey;
  if(S.ground) S.ground.remove();
  const g=createGraphics(W,Hh); g.colorMode(HSB,360,100,100,100); g.noStroke();
  const fr=i=>{const s=Math.sin(i*127.1+(P.seed|0)*311.7)*43758.5453; return s-Math.floor(s);};
  let bh,bs,bb;
  if(st==='leaf'){bh=46;bs=15;bb=80;}
  else if(st==='cyanotype'){bh=214;bs=76;bb=22;}
  else if(st==='nerve'){bh=350;bs=48;bb=8;}
  else if(st==='ink'){bh=40;bs=11;bb=80;}
  else {bh=188;bs=64;bb=16;} // hyphae deep teal
  g.fill(bh,bs,bb); g.rect(0,0,W,Hh);
  const dark=(st==='hyphae'||st==='nerve'||st==='cyanotype');
  if(dark){
    const gx=clp(P.x,.15,.85)*W, gy=clp(P.y,.15,.85)*Hh;
    for(let i=0;i<64;i++){const f=i/63;
      g.fill(bh, clp(bs-16*f,10,90), lrp(bb+(st==='cyanotype'?9:15), bb, f), 8);
      g.ellipse(gx,gy,u*(2.0-f*1.7),u*(2.0-f*1.7));}
  }
  if(st==='ink'||st==='leaf'){
    for(let i=0;i<2200;i++){ g.fill(30,12, fr(i*3+7)<.5?70:100, 4); g.rect(fr(i*3+8)*W, fr(i*3+9)*Hh, 1.5,1.5); }
  }
  // soft corner vignette for depth (all styles)
  g.noFill();
  for(let i=0;i<34;i++){const f=i/33; g.stroke(bh,bs,0,3); g.strokeWeight(u*0.03);
    g.ellipse(W/2,Hh/2, W*1.5-f*W*0.7, Hh*1.5-f*Hh*0.7);}
  g.noStroke();
  S.ground=g;
}

// ---------- growth state (local coords, origin-centered) ----------
const R=u*0.42;
const NA=Math.round(70+dens*330);
const cap=Math.round(350+dens*1250);
const di=u*(0.09+clp(P.spread,0,1)*0.13);
const dk=u*0.03;
const seg=u*0.016;
const bkey=W+'x'+Hh+'|'+st+'|'+(P.seed|0)+'|'+(S.gen||0)+'|'+Math.round(dens*10)+'|'+Math.round(clp(P.spread,0,1)*10);
if(!S.nodes || S.bkey!==bkey){
  S.bkey=bkey;
  let z=(((P.seed|0)*2654435761) ^ ((S.gen||0)*40503) ^ 0x9e3779b9)>>>0;
  const rnd=()=>{ z=(z*1664525+1013904223)>>>0; return z/4294967296; };
  S.attr=[];
  for(let i=0;i<NA;i++){ const a=rnd()*6.2832, rr=R*Math.sqrt(rnd());
    S.attr.push({x:Math.cos(a)*rr, y:Math.sin(a)*rr*0.86 - R*0.12}); }
  S.nodes=[{x:0,y:R*0.82,par:-1,depth:0,flow:1,ch:0}];
  S.done=false; S.doneAt=K.t; S.buildT=K.t;
}

// ---------- grow a few iterations / frame ----------
let iters = S.done ? 0 : Math.max(1, Math.round((0.8+P.speed*2.2)*(0.5+intn) + A.bass*3));
if(P.act==='breathe') iters=Math.max(1,Math.round(iters*(0.55+1.2*intn)));
for(let it=0; it<iters && !S.done; it++){
  const nodes=S.nodes, attr=S.attr, cs=di;
  const grid=new Map();
  for(let i=0;i<nodes.length;i++){ const p=nodes[i];
    const k=Math.floor(p.x/cs)+','+Math.floor(p.y/cs); let b=grid.get(k); if(!b){b=[];grid.set(k,b);} b.push(i); }
  const pull=new Map();
  for(let ai=attr.length-1; ai>=0; ai--){ const a=attr[ai];
    let best=-1, bd=di*di; const bx=Math.floor(a.x/cs), by=Math.floor(a.y/cs);
    for(let ox=-1;ox<=1;ox++)for(let oy=-1;oy<=1;oy++){ const b=grid.get((bx+ox)+','+(by+oy)); if(!b)continue;
      for(let jj=0;jj<b.length;jj++){ const j=b[jj], p=nodes[j], dx=p.x-a.x, dy=p.y-a.y, d2=dx*dx+dy*dy;
        if(d2<bd){bd=d2;best=j;} } }
    if(best<0) continue;
    if(bd<dk*dk){ attr.splice(ai,1); continue; }
    const p=nodes[best], d=Math.sqrt(bd)||1; let e=pull.get(best)||{dx:0,dy:0};
    e.dx+=(a.x-p.x)/d; e.dy+=(a.y-p.y)/d; pull.set(best,e);
  }
  if(pull.size===0 || nodes.length>=cap){ S.done=true; S.doneAt=K.t; break; }
  pull.forEach((e,idx)=>{ if(nodes.length>=cap) return;
    const m=Math.hypot(e.dx,e.dy)||1, p=nodes[idx];
    const nx=p.x+e.dx/m*seg, ny=p.y+e.dy/m*seg;
    nodes.push({x:nx,y:ny,par:idx,depth:p.depth+1,flow:1,ch:0});
    p.ch=(p.ch||0)+1;
    let k=idx, guard=0; while(k>=0 && guard++<2000){ nodes[k].flow++; k=nodes[k].par; }
  });
}
// failsafe reseed if a growth stalls before exhausting attractors
if(!S.done && K.t-S.buildT>34){ S.done=true; S.doneAt=K.t; }
// hold the finished figure, then reseed a fresh one (perpetual novelty)
const holdT = P.act==='prune'?2.0 : (P.act==='breathe'?3.5:5.0);
if(S.done && K.t-S.doneAt>holdT){ S.gen=(S.gen||0)+1; S.nodes=null; }

// ---------- draw ----------
if(aMul<1) tint(0,0,100,P.alpha);
image(S.ground,0,0,W,Hh);
noTint();

const nodes=S.nodes, n=nodes?nodes.length:0;
if(n>0){
  const anchorX=clp(P.x,.12,.88)*W, anchorY=clp(P.y,.12,.88)*Hh;
  const sc=clp(P.scale,.4,2.2)*(1+0.03*Math.sin(K.t*0.21));
  const orbX=Math.sin(K.t*0.11)*u*0.035, orbY=Math.cos(K.t*0.083)*u*0.035;
  const rot=K.t*0.028 + Math.sin(K.t*0.05)*0.06;
  const wob=u*0.010*(0.6+0.7*en);
  const wx=new Float32Array(n), wy=new Float32Array(n);
  for(let i=0;i<n;i++){ const p=nodes[i];
    wx[i]=p.x + wob*Math.sin(K.t*0.8 + i*0.37);
    wy[i]=p.y + wob*Math.cos(K.t*0.7 + i*0.31); }
  const wBase=u*0.0016;
  const sapSp=1.6*clp(P.speed,.2,3), sapK=0.16;
  const taperExp=0.30+clp(P.taper,0,1)*0.40;

  push();
  translate(anchorX+orbX, anchorY+orbY);
  rotate(rot);
  scale(sc);
  strokeCap(ROUND);
  noFill();

  if(st==='hyphae'||st==='nerve'){
    const baseHue = st==='nerve'?350:md(P.hue,360);
    // soft wide underlay glow (BLEND, low alpha -> no runaway)
    for(let i=1;i<n;i++){ const p=nodes[i], par=p.par; if(par<0)continue;
      const w=wBase*(0.6+clp(Math.pow(p.flow,taperExp),1,9));
      const sap=0.5+0.5*Math.sin(K.t*sapSp - p.depth*sapK);
      const br=clp(0.45+0.5*sap*(0.5+en)+A.treble*0.5*sap,0,1);
      const hh=md(baseHue+p.depth*0.6+(st==='nerve'?sap*30:sap*14),360);
      stroke(hh, st==='nerve'?70:60, 55*br, 16*aMul);
      strokeWeight(w*2.6);
      line(wx[par],wy[par],wx[i],wy[i]); }
    // bright cores
    for(let i=1;i<n;i++){ const p=nodes[i], par=p.par; if(par<0)continue;
      const w=wBase*(0.6+clp(Math.pow(p.flow,taperExp),1,9));
      const sap=0.5+0.5*Math.sin(K.t*sapSp - p.depth*sapK);
      const br=clp(0.5+0.55*sap*(0.5+en)+A.treble*0.6*sap,0,1.2);
      const hh=md(baseHue+p.depth*0.5,360);
      const sat=st==='nerve'?80:clp(85-p.depth*0.3,42,90);
      stroke(hh, sat, clp(70+40*br,0,100), clp((70+25*sap)*aMul,0,100));
      strokeWeight(w);
      line(wx[par],wy[par],wx[i],wy[i]); }
    // additive swells at branch points / tips (few)
    blendMode(ADD); noStroke();
    let cnt=0;
    for(let i=1;i<n && cnt<90;i++){ const p=nodes[i];
      if((p.ch||0)>=2){ const sap=0.5+0.5*Math.sin(K.t*sapSp - p.depth*sapK);
        fill(md(baseHue+(st==='nerve'?10:20),360), st==='nerve'?70:55, 100, clp((8+sap*14)*aMul+A.treble*20*aMul,0,100));
        circle(wx[i],wy[i], wBase*(3+4*sap)); cnt++; } }
    blendMode(BLEND); noFill();
  } else if(st==='leaf'){
    for(let i=1;i<n;i++){ const p=nodes[i], par=p.par; if(par<0)continue;
      const w=wBase*(0.7+clp(Math.pow(p.flow,taperExp),1,10));
      const dr=clp(p.depth/26,0,1);
      const hh=lrp(38,120,dr);
      const sap=0.5+0.5*Math.sin(K.t*sapSp - p.depth*sapK);
      stroke(hh, lrp(72,72,dr), lrp(40,54,dr), clp((78+8*sap)*aMul,0,100));
      strokeWeight(w);
      line(wx[par],wy[par],wx[i],wy[i]); }
  } else if(st==='cyanotype'){
    const lw=Math.max(0.8,u*0.0011);
    strokeWeight(lw);
    for(let i=1;i<n;i++){ const p=nodes[i], par=p.par; if(par<0)continue;
      const sap=0.5+0.5*Math.sin(K.t*sapSp - p.depth*sapK);
      stroke(200,12,100, clp((70+20*sap)*aMul,0,100));
      line(wx[par],wy[par],wx[i],wy[i]); }
    // schematic node ticks at branch points
    stroke(200,20,100,60*aMul); strokeWeight(lw);
    let cnt=0;
    for(let i=1;i<n && cnt<170;i++){ const p=nodes[i];
      if((p.ch||0)>=2){ const t=u*0.006;
        line(wx[i]-t,wy[i],wx[i]+t,wy[i]); line(wx[i],wy[i]-t,wx[i],wy[i]+t); cnt++; } }
  } else { // ink-root sumi
    for(let i=1;i<n;i++){ const p=nodes[i], par=p.par; if(par<0)continue;
      const w=wBase*(0.7+clp(Math.pow(p.flow,taperExp+0.1),1,12));
      const jit=1+0.18*Math.sin(K.t*0.9+i*1.7);
      const sap=0.5+0.5*Math.sin(K.t*sapSp - p.depth*sapK);
      stroke(28,22, lrp(24,12, clp(p.flow/40,0,1)), clp((80+10*sap)*aMul,0,100));
      strokeWeight(w*jit);
      line(wx[par],wy[par],wx[i],wy[i]); }
  }
  pop();
}
drawingContext.shadowBlur=0;
blendMode(BLEND);
